n=imageinfo&utm_content=thumbnail","file":"Jigsaw puzzle 01 by Scouten.jpg","source":"https://commons.wikimedia.org/wiki/File:Jigsaw_puzzle_01_by_Scouten.jpg","provider":"wikimedia","attribution":{"author":"Scouten","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0","source_url":"https://commons.wikimedia.org/wiki/File:Jigsaw_puzzle_01_by_Scouten.jpg"},"width":960,"height":638},"memberships":["project","hobby","writer"]},{"category":"project","title":"Fanzin Hazırlama","description":"Yazı, çizim ve fotoğrafları bir tema etrafında küçük bir bağımsız yayında birleştir.","slug":"make","reference":"https://en.wikipedia.org/wiki/Zine","illustrative":true,"cover":{"url":"https://upload.wikimedia.org/wikipedia/commons/c/c6/SF_punk_zines_at_Prelinger_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled","file":"SF punk zines at Prelinger Library.jpg","source":"https://commons.wikimedia.org/wiki/File:SF_punk_zines_at_Prelinger_Library.jpg","provider":"wikimedia","attribution":{"author":"Lindsay Eyink","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0","source_url":"https://commons.wikimedia.org/wiki/File:SF_punk_zines_at_Prelinger_Library.jpg"},"width":960,"height":960},"memberships":["project","hobby","writer"]},{"category":"project","title":"Dijital Hikâye Hazırlama","description":"Fotoğraf, ses ve kısa metinleri kullanarak paylaşılabilir bir dijital anlatı üret.","slug":"make","reference":"https://en.wikipedia.org/wiki/Digital_storytelling","illustrative":true,"cover":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Desiger_Working_In_Mozilla_Taiwan_Office_%2872739467%29.jpeg/960px-Desiger_Working_In_Mozilla_Taiwan_Office_%2872739467%29.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","file":"Desiger Working In Mozilla Taiwan Office (72739467).jpeg","source":"https://commons.wikimedia.org/wiki/File:Desiger_Working_In_Mozilla_Taiwan_Office_(72739467).jpeg","provider":"wikimedia","description":"500px provided description: Desiger Working In Mozilla Taiwan Office [#mozilla ,#Taipei ,#Office]","attribution":{"author":"Oliver Propst","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0","source_url":"https://commons.wikimedia.org/wiki/File:Desiger_Working_In_Mozilla_Taiwan_Office_(72739467).jpeg"},"width":960,"height":720},"memberships":["project","hobby","writer"]},{"category":"project","title":"Aile Tarif Defteri","description":"Aileden izin alarak tarifleri, küçük hikâyeleri ve fotoğrafları ortak bir defterde topla.","slug":"make","reference":"https://en.wikipedia.org/wiki/Recipe_book","illustrative":true,"cover":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Esther_Staat_Recipe_-_DPLA_-_efe735d152436947171c1bf0a277dd94_%28page_2%29.jpg/960px-Esther_Staat_Recipe_-_DPLA_-_efe735d152436947171c1bf0a277dd94_%28page_2%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","file":"Esther Staat Recipe - DPLA - efe735d152436947171c1bf0a277dd94 (page 2).jpg","source":"https://commons.wikimedia.org/wiki/File:Esther_Staat_Recipe_-_DPLA_-_efe735d152436947171c1bf0a277dd94_(page_2).jpg","provider":"wikimedia","description":"A recipe for \"Ann's key lime pie\" handwritten by Esther Staat. Esther Staat (1925-2021) was known as “Sister Salad,” for her work making salads in two popular Columbus restaurants: the Christopher Inn, where she prepared Dave Saxton’s salad recipe, and Fifty Five on the Boulevard, where she made the 55 salad for decades, using Richard Stopper and Charles Langstaff’s recipe. After Fifty Five went out of business, for three days a week Staat continued to make the 55 salad at the Polaris Grill, where it is still on the menu. In addition to her salad work, Staat worked at ACT, Inc. She also started working at the Value City Arena when it opened in 1998, and continued working there for at least nineteen years.","attribution":{"author":"","license":"Public domain","license_url":null,"source_url":"https://commons.wikimedia.org/wiki/File:Esther_Staat_Recipe_-_DPLA_-_efe735d152436947171c1bf0a277dd94_(page_2).jpg"},"width":960,"height":1143},"memberships":["project","hobby","writer"]},{"category":"project","title":"Mahalle Ses Haritası","description":"İzinlere ve kişisel mahremiyete dikkat ederek çevrenin seslerini kaydet ve bir harita üzerinde birleştir.","slug":"make","reference":"https://en.wikipedia.org/wiki/Sound_map","illustrative":true,"cover":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Marcel_Gnauk_from_Free_To_Use_Sounds_recording_sounds_in_Iceland.jpg/960px-Marcel_Gnauk_from_Free_To_Use_Sounds_recording_sounds_in_Iceland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","file":"Marcel Gnauk from Free To Use Sounds recording sounds in Iceland.jpg","source":"https://commons.wikimedia.org/wiki/File:Marcel_Gnauk_from_Free_To_Use_Sounds_recording_sounds_in_Iceland.jpg","provider":"wikimedia","description":"Marcel Gnauk from Free To Use Sounds recording sounds in Iceland","attribution":{"author":"Free To Use Sounds","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0","source_url":"https://commons.wikimedia.org/wiki/File:Marcel_Gnauk_from_Free_To_Use_Sounds_recording_sounds_in_Iceland.jpg"},"width":960,"height":640},"memberships":["project","hobby","writer"]},{"category":"project","title":"Kişisel İnternet Sitesi Yapımı","description":"Kendini, üretimlerini veya bir konuyu anlatan erişilebilir bir internet sitesi tasarla ve hazırla.","slug":"make","reference":"https://en.wikipedia.org/wiki/Web_design","illustrative":true,"cover":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Pexels-luis-gomes-546819.jpg/960px-Pexels-luis-gomes-546819.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","file":"Pexels-luis-gomes-546819.jpg","source":"https://commons.wikimedia.org/wiki/File:Pexels-luis-gomes-546819.jpg","provider":"wikimedia","description":"Programming","attribution":{"author":"luis gomes","license":"CC0","license_url":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source_url":"https://commons.wikimedia.org/wiki/File:Pexels-luis-gomes-546819.jpg"},"width":960,"height":638},"memberships":["project","hobby","writer"]},{"category":"project","title":"Masaüstü Düzenleyici Yapımı","description":"Çalışma alanına uygun ölçülerde bir masaüstü düzenleyici tasarla ve üret.","slug":"make","reference":"https://en.wikipedia.org/wiki/Desk","illustrative":true,"cover":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Example_of_3D_print_9%2C_Claes_Lindhardt_penholder.png/960px-Example_of_3D_print_9%2C_Claes_Lindhardt_penholder.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail","file":"Example of 3D print 9, Claes Lindhardt penholder.png","source":"https://commons.wikimedia.org/wiki/File:Example_of_3D_print_9,_Claes_Lindhardt_penholder.png","provider":"wikimedia","description":"3D print example, printes is: A printed version of: https://commons.wikimedia.org/wiki/File:Claes_Lindhardt%E2%80%93Inspired_desktop_utensil_Holder.stl","attribution":{"author":"BoardGamesN3Dprint","license":"CC0","license_url":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source_url":"https://commons.wikimedia.org/wiki/File:Example_of_3D_print_9,_Claes_Lindhardt_penholder.png"},"width":960,"height":1280},"memberships":["project","hobby","writer"]}]}$data$::jsonb;
 c jsonb; r jsonb; v_target uuid; v_seed_type uuid; v_admin uuid;
 v_claim text:=current_setting('request.jwt.claim.sub',true);
 v_meta jsonb; v_types jsonb; v_links jsonb; v_history_before text; v_history_after text;
 v_created integer:=0; v_reused integer:=0; v_count integer;
begin
 perform pg_advisory_xact_lock(hashtext(p->>'batch'));
 select user_id into v_admin from public.admin_users order by created_at limit 1;
 if v_admin is null then raise exception 'No authorized catalogue admin'; end if;
 perform set_config('request.jwt.claim.sub',v_admin::text,true);

 select md5(coalesce(string_agg(to_jsonb(s)::text,'' order by s.id),'')) into v_history_before
 from public.seeds s where s.canonical_target_id in (
   select (x->>'existing_target')::uuid from jsonb_array_elements(p->'rows') x where x->>'existing_target' is not null);

 for c in select value from jsonb_array_elements(p->'categories') loop
   if exists(select 1 from public.uin_content_types where id=c->>'id' and (label<>c->>'label' or base_kind<>'activity')) then raise exception 'Category collision: %',c->>'id';end if;
   perform public.admin_save_uin_content_type_v58(c->>'id',c->>'label',c->>'icon','activity',true,c->'ui_labels'||'{"search_provider":"manual"}'::jsonb);
   update public.uin_content_types set position=(c->>'position')::integer, search_kind='activity' where id=c->>'id';
 end loop;

 for r in select value from jsonb_array_elements(p->'rows') loop
   v_target:=null;
   select id into v_target from public.canonical_targets
     where editorial_metadata->>'catalogue_batch'=p->>'batch' and editorial_metadata->>'catalogue_title'=r->>'title';
   if v_target is null and r->>'existing_target' is not null then
     select id into v_target from public.canonical_targets where id=(r->>'existing_target')::uuid and title=r->>'title';
     if v_target is null then raise exception 'Existing target changed: %',r->>'title';end if;
     v_reused:=v_reused+1;
   elsif v_target is null then
     if exists(select 1 from public.seed_catalog_items where status='active' and normalized_title=public.normalize_seed_catalog_text(r->>'title') and coalesce(metadata->>'content_type_id',item_kind) in ('activity','hobby','writer','director','sport','food','route','volunteering','project')) then
       raise exception 'Unreviewed existing card: %',r->>'title';
     end if;
     select id into v_seed_type from public.seed_types where slug=r->>'slug' and is_active;
     if v_seed_type is null then raise exception 'Missing seed type: %',r->>'slug';end if;
     v_target:=public.admin_create_uin_card_v59(v_seed_type,r->>'category',r->>'title',null,r#>>'{cover,url}',r->>'description',r->>'reference');
     v_created:=v_created+1;
   end if;
   select editorial_metadata into v_meta from public.canonical_targets where id=v_target for update;
   select jsonb_agg(distinct x) into v_types from jsonb_array_elements_text(
     coalesce(v_meta->'content_type_ids','[]'::jsonb)||coalesce(r->'memberships','[]'::jsonb)||jsonb_build_array(v_meta->>'content_type_id',r->>'category')) x where x is not null;
   if jsonb_array_length(v_types)>3 then raise exception 'Category limit for %',r->>'title';end if;
   v_links:=jsonb_build_array(
     jsonb_build_object('label',case when r->>'category'='route' then 'Rota bilgisi' else 'İçerik hakkında' end,'url',r->>'reference'),
     jsonb_build_object('label','Fotoğraf: '||(r#>>'{cover,attribution,author}')||' · '||(r#>>'{cover,attribution,license}'),'url',r#>>'{cover,source}')
   );
   if r#>>'{cover,attribution,license_url}' is not null then
     v_links:=v_links||jsonb_build_array(jsonb_build_object('label','Fotoğraf kullanım lisansı','url',r#>>'{cover,attribution,license_url}'));
   end if;
   update public.canonical_targets set
     editorial_cover_url=r#>>'{cover,url}',
     editorial_metadata=v_meta||jsonb_build_object(
       'content_type_ids',v_types,'description',r->>'description','reference_url',r->>'reference','reference_links',v_links,
       'image_attribution',r#>'{cover,attribution}','attribution_url',r#>>'{cover,source}',
       'cover_source_url',r#>>'{cover,source}','cover_provider','wikimedia','cover_is_illustrative',(r->>'illustrative')::boolean,
       'catalogue_batch',p->>'batch','catalogue_title',r->>'title','language','tr'
     ),updated_at=now()
   where id=v_target;
   if not exists(select 1 from public.uin_card_content_types_v177 where target_id=v_target and content_type_id=r->>'category') then raise exception 'Missing membership: %',r->>'title';end if;
 end loop;

 for c in select value from jsonb_array_elements(p->'categories') loop
   select count(distinct t.id) into v_count from public.canonical_targets t join public.uin_card_content_types_v177 m on m.target_id=t.id
   where m.content_type_id=c->>'id' and t.editorial_metadata->>'catalogue_batch'=p->>'batch' and t.editorial_cover_url is not null;
   if v_count<>10 then raise exception 'Expected 10 illustrated cards for %, got %',c->>'id',v_count;end if;
 end loop;
 select md5(coalesce(string_agg(to_jsonb(s)::text,'' order by s.id),'')) into v_history_after
 from public.seeds s where s.canonical_target_id in (
   select (x->>'existing_target')::uuid from jsonb_array_elements(p->'rows') x where x->>'existing_target' is not null);
 if v_history_before is distinct from v_history_after then raise exception 'Personal records changed unexpectedly';end if;
 perform set_config('request.jwt.claim.sub',coalesce(v_claim,''),true);
 raise notice 'New cards: %, reused cards: %',v_created,v_reused;
end;
$seed$;
commit;
select uin_private.refresh_category_counts();
select count(*) illustrated_cards from public.canonical_targets where editorial_metadata->>'catalogue_batch'='uin-shared-catalogue-20261018';
